    #include <bits/stdc++.h>
using namespace std;

class Node {
public:
    Node* one;
    Node* zero;
    Node() {
        one = nullptr;
        zero = nullptr;
    }
};

class Trie {
public:
    Node* root;
    Trie() { 
        root = new Node(); 
    }

    // Function to insert in Trie
    void insert(int n) {

        Node* curr = root;
        for (int i = 31; i >= 0; i--) {
            int bit = (n >> i) & 1;

            // Check if the bit is 0
            if (bit == 0) {
                if (curr->zero == NULL) {
                    curr->zero = new Node();
                }
                curr = curr->zero;
            }

            // Else if bit is 1
            else {
                if (curr->one == NULL) {
                    curr->one = new Node();
                }
                curr = curr->one;
            }
        }
    }

    // Function to find element having 
    // the maximum XOR with value n
    int findXOR(int n) {
        Node* curr = root;
        int res = 0;

        for (int i = 31; i >= 0; i--) {
            int bit = (n >> i) & 1;

            // if the bit is 0
            if (bit == 0) {

                // if set bit is present
                if (curr->one) {
                    curr = curr->one;
                    res += (1 << i);
                }
                else {
                    curr = curr->zero;
                }
            }

            // Else if bit is 1
            else {

                // if unset bit is present
                if (curr->zero) {
                    curr = curr->zero;
                    res += (1 << i);
                }
                else {
                    curr = curr->one;
                }
            }
        }
        return res;
    }

};

